// Pure side of an agent type's definition: where its file is and which model and effort its
// frontmatter pins. `agent.spawn` carries the Agent call's `model` only, never the definition's
// (measured 2026-10-14: memory-writer, defined haiku, spawned with `model` undefined and resolved
// to claude-haiku-5-5 below the hook), so the router reads the file itself.

// source: ~/.claude/plugins/installed_plugins.json, the engine's record of installed plugins;
// `plugins["<name>@<marketplace>"][0].installPath` is the folder a session runs.
export const INSTALLED_PLUGINS_PATH = '~/.claude/plugins/installed_plugins.json'

// source: measured 2026-10-14 with a probe mod (agent.spawn result, turn.step): Explore, Plan and
// general-purpose spawned with no `model` from an opus parent resolved to the parent's model.
export const INHERITING_BUILT_INS: readonly string[] = ['Explore', 'Plan', 'general-purpose']

export type Definition = { model?: string; effort?: string }

// The folders from `dir` up to the filesystem root, nearest first; `/` and `\\` both separate.
export const ancestors = (dir: string): string[] => {
  const out: string[] = []
  let current = dir.length > 1 ? dir.replace(/[\\/]+$/, '') : dir
  for (;;) {
    out.push(current)
    const cut = Math.max(current.lastIndexOf('/'), current.lastIndexOf('\\'))
    if (cut < 0) return out
    if (cut === 0) return current === '/' ? out : [...out, '/']
    current = current.slice(0, cut)
  }
}

type Install = { scope?: unknown; projectPath?: unknown; installPath?: unknown }

// source: Claude Code's settings precedence (local over project over user), applied to the scopes
// `installed_plugins.json` records (`scope`: user, project, local; `projectPath` for the last two,
// measured 2026-10-14 on ~/.claude/plugins/installed_plugins.json). The engine's own choice among
// several entries is not documented in the mods reference: this order is the assumption (issue #11).
const USER = 2
const SCOPE_RANK: Record<string, number> = { local: 0, project: 1, user: USER }
const norm = (p: string): string => p.replace(/\\/g, '/').replace(/\/+$/, '')

// The install path a session in `cwd` runs: among the entries whose scope covers the session (user
// entries always, project and local ones when their `projectPath` is `cwd` or a folder above it) the
// narrowest scope, then the first listed. An entry with no scope is the user's.
export const activeInstallPath = (installs: readonly Install[], cwd: string): string | undefined => {
  const here = new Set(ancestors(cwd).map(norm))
  const covering: { path: string; rank: number }[] = []
  for (const i of installs) {
    if (typeof i.installPath !== 'string' || i.installPath === '') continue
    const rank = typeof i.scope === 'string' ? (SCOPE_RANK[i.scope] ?? USER) : USER
    if (rank !== USER && !(typeof i.projectPath === 'string' && here.has(norm(i.projectPath)))) continue
    covering.push({ path: i.installPath, rank })
  }
  // Array.prototype.sort is stable: equal ranks keep their listed order.
  return covering.sort((x, y) => x.rank - y.rank)[0]?.path
}

// The files that may define a type, in the engine's precedence: a plugin's `agents/<name>.md`
// for `<plugin>:<name>` (`agents/<sub>/<name>.md` for `<plugin>:<sub>:<name>`) from the install
// that runs in `cwd`, else the project's `.claude/agents/` in each of `projectDirs` (the folders from
// the working directory up to the repository root, nearest first), then the user's (`claudeDir`, the
// engine's config directory: `~/.claude` or CLAUDE_CONFIG_DIR).
export const definitionPaths = (
  type: string,
  installedPluginsJson: string | undefined,
  claudeDir: string,
  cwd: string,
  projectDirs: readonly string[],
): string[] => {
  const colon = type.indexOf(':')
  if (colon < 0) return [...projectDirs.map((dir) => `${dir}/.claude/agents/${type}.md`), `${claudeDir}/agents/${type}.md`]
  const plugin = type.slice(0, colon)
  // `<plugin>:<sub>:<name>` is the plugin's agents/<sub>/<name>.md.
  const name = type.slice(colon + 1).split(':').join('/')
  if (installedPluginsJson === undefined) return []
  let parsed: { plugins?: Record<string, Install[]> }
  try {
    parsed = JSON.parse(installedPluginsJson) as typeof parsed
  } catch (error) {
    // A record that is not JSON is not "plugin not installed": the caller is told which it is.
    throw new Error(`installed_plugins.json is not valid JSON (${error instanceof Error ? error.message : String(error)})`.slice(0, 160))
  }
  return Object.entries(parsed.plugins ?? {})
    .filter(([key]) => key.startsWith(`${plugin}@`))
    .map(([, installs]) => activeInstallPath(installs, cwd))
    .filter((p): p is string => p !== undefined)
    .map((root) => `${root}/agents/${name}.md`)
}

// The `model:` and `effort:` lines of the leading `---` block; a file without one pins nothing.
export const parseDefinition = (md: string): Definition => {
  const block = /^---\r?\n([\s\S]*?)\r?\n---/.exec(md)
  if (block === null) return {}
  const field = (name: string): string | undefined => {
    const m = new RegExp(`^${name}:[ \\t]*["']?([^"'\\s#]+)`, 'm').exec(block[1] ?? '')
    return m?.[1]
  }
  const model = field('model')
  const effort = field('effort')
  return { ...(model === undefined ? {} : { model }), ...(effort === undefined ? {} : { effort }) }
}

// The model a definition pins; `inherit` and an absent line both leave it to the parent.
export const pinnedModel = (d: Definition): string | undefined =>
  d.model === undefined || d.model === 'inherit' ? undefined : d.model

files.hooks/paths.ts:
// Where `~/` lands on the machine a mod runs on. Pure: the engine follows `$` only inside the module
// that spells it, so each mod's register file reads the three variables and hands their values here.
//
// This file exists once per mod that expands `~/` (a mod cannot import a file from another mod: the
// engine refuses it, "outside the plugin's folder"), and every copy is byte-identical;
// scripts/check-shared.sh fails when one differs.

export type PathVars = { home: string | undefined; userProfile: string | undefined; configDir: string | undefined }
export type Placed = { path: string } | { reason: string }

const isSet = (value: string | undefined): value is string => value !== undefined && value !== ''
const trimmed = (dir: string): string => dir.replace(/[\\/]+$/, '')

// source: HOME is the home on macOS and Linux, USERPROFILE on Windows (cmd and PowerShell set it,
// not HOME); Node's os.homedir() reads them in that order on each platform. Unset in a sandbox: no
// place, said as such, never `/`.
export const homeOf = (vars: PathVars): Placed =>
  isSet(vars.home) ? { path: trimmed(vars.home) } : isSet(vars.userProfile) ? { path: trimmed(vars.userProfile) } : { reason: 'neither HOME nor USERPROFILE is set' }

// source: CLAUDE_CONFIG_DIR relocates the engine's `~/.claude` (plugins/, reference/, settings.json);
// without it the config directory is `<home>/.claude`.
export const configDirOf = (vars: PathVars): Placed => {
  if (isSet(vars.configDir)) return { path: trimmed(vars.configDir) }
  const home = homeOf(vars)

  return 'path' in home ? { path: `${home.path}/.claude` } : home
}

const CONFIG_PREFIX = '~/.claude'

// A path as the mods spell it: `~/.claude/...` is under the config directory, any other `~/...` under
// the home, anything else is already a place.
export const placePath = (vars: PathVars, path: string): Placed => {
  if (!path.startsWith('~/')) return { path }
  const isConfig = path === CONFIG_PREFIX || path.startsWith(`${CONFIG_PREFIX}/`)
  const base = isConfig ? configDirOf(vars) : homeOf(vars)
  if ('reason' in base) return { reason: `${path} has no place: ${base.reason}` }

  return { path: `${base.path}/${path.slice(isConfig ? CONFIG_PREFIX.length + 1 : 2)}` }
}

files.hooks/dispatch.ts:
// Pure half of the dispatch decision for one spawn: what its DESIGN block says, whether its task is classified, how the
// classifier is asked and read, and the rung the table (dispatch-table.ts) gives a class. Precedence per dimension,
// first match wins: explicit (call, definition, fork/workflow/teammate) > DESIGN > table (route.ts for the model,
// effort.ts for the effort). A failed classifier decides nothing; no pressure is an input here.
// source: ADR-9851

import { type Definition, pinnedModel } from './agents'
import { parseDesign } from './design'
import type { Effort } from './policy'
import { FAMILIES, type Family, type TaskClass } from './route'

// One rung of the table: the alias the Agent tool takes (AgentInput.model) and the effort its steps run at.
export type Rung = { readonly model: 'haiku' | 'sonnet' | 'opus'; readonly effort: Effort; readonly source: string }

export type DispatchTable = {
  readonly version: number
  readonly classifier: { readonly model: string; readonly effort: Effort; readonly maxTokens: number; readonly promptHeadChars: number }
  readonly rows: Readonly<Record<TaskClass, Rung>>
  readonly review: Readonly<Record<TaskClass, Rung>>
}

// Mirrors the zetetic-genius contract (its classify.ts TASK_CLASSES), in the order of the effort they call for.
export const TASK_CLASSES: readonly TaskClass[] = ['routine', 'planned', 'bugfix', 'analysis', 'critical']

const EFFORTS: readonly Effort[] = ['low', 'medium', 'high', 'xhigh', 'max']

// What a DESIGN block decides: the one model family it names, the effort level it names; `refused` each value it
// stated that is neither (a DESIGN field is free text), named in a row and never guessed at.
export type Designed = { model?: Family; effort?: Effort; refused: string[] }

const familyNamed = (text: string): Family | undefined => {
  const t = text.toLowerCase()
  const named = FAMILIES.filter((f) => t.includes(f))
  return named.length === 1 ? named[0] : undefined
}

const effortNamed = (text: string): Effort | undefined => {
  const first = text.trim().toLowerCase().split(/[\s(,;]/)[0] ?? ''
  return EFFORTS.find((e) => e === first)
}

export const designOf = (prompt: string): Designed => {
  const block = parseDesign(prompt)
  if (block === null) return { refused: [] }
  const refused: string[] = []
  const model = block.model === null ? undefined : familyNamed(block.model)
  if (block.model !== null && model === undefined) refused.push(`model '${block.model}' names no single model family`)
  const effort = block.effort === null ? undefined : effortNamed(block.effort)
  if (block.effort !== null && effort === undefined) refused.push(`effort '${block.effort}' is not an effort level`)
  return { ...(model === undefined ? {} : { model }), ...(effort === undefined ? {} : { effort }), refused }
}

// What the spawn tells before any completion: `seen` its Agent call was seen at tool.call (a hook's own spawn and a
// message resuming an agent are not), `resumed` it resumes an agent, `definition` undefined when it could not be read.
export type DispatchFacts = {
  fixed: boolean
  seen: boolean
  resumed: boolean
  callModel: string | undefined
  definition: Definition | undefined
  design: Designed
}

// The one case a completion is spent on: a model's own Agent call for an inheriting type (definition read, no model
// pin), naming no model, whose prompt designs neither model nor effort (a DESIGN of task, check and shape designs nothing).
export const classifiable = (f: DispatchFacts): boolean =>
  !f.fixed &&
  f.seen &&
  !f.resumed &&
  f.callModel === undefined &&
  f.definition !== undefined &&
  pinnedModel(f.definition) === undefined &&
  f.design.model === undefined &&
  f.design.effort === undefined

export type Classification = { cls: TaskClass; review: boolean }
// undefined: nobody asked; `failed`: asked, and no class came back (the reason, for the row).
export type Classified = Classification | { failed: string } | undefined

// The five class definitions are the zetetic-genius classifier's (classify.ts): a spawn and the request it came from
// are graded on one scale.
export const CLASSIFIER_SYSTEM = [
  'You classify one task an orchestrator hands to a coding subagent. Answer with one JSON object and nothing else:',
  '{"task_class": <class>, "review": <true or false>}',
  '',
  'task_class is exactly one of:',
  '- routine: reading, listing, searching, formatting, a one-line change, a question answered from files.',
  '- planned: implementing a plan or spec that is already written out in the request.',
  '- bugfix: a bug whose cause is clear or quickly located.',
  '- analysis: an architecture decision, a design, a research synthesis, a multi-file feature.',
  '- critical: formal correctness, concurrency, security, billing, data loss; a wrong answer is worse than a slow one.',
  '',
  'review is true when the task is to review, audit or verify work that already exists (code, a diff, a pull request,',
  'a document, a list of findings) and to report on it; false when the task produces the work itself.',
  // Measured 2026-10-20 (docs/verification/autopilot-dispatch-table-replay-2026-10-20.md): without this line haiku
  // answered task_class "review" for 7 of 47 ledger prompts.
  'A review is never a task_class: it takes the class of the work it reviews, and review is true.',
  'Grade the task the subagent is given, not the topic it touches.',
].join('\n')

// What the classifier reads: the agent type and the description (the orchestrator's summary), then the prompt's head.
export const classifierPrompt = (type: string, description: string, prompt: string, headChars: number): string =>
  `Agent type: ${type}\nDescription: ${description}\n\nTask:\n${prompt.slice(0, headChars)}`

// Strict: a JSON object, fenced or bare, with a known class and a boolean review; anything else is no class.
export const parseClass = (answer: string): Classification | undefined => {
  const match = /\{[\s\S]*\}/.exec(answer)
  if (match === null) return undefined
  let raw: unknown
  try {
    raw = JSON.parse(match[0])
  } catch {
    return undefined
  }
  const o = raw as { task_class?: unknown; review?: unknown } | null
  if (o === null || typeof o !== 'object') return undefined
  const cls = TASK_CLASSES.find((c) => c === o.task_class)
  if (cls === undefined || typeof o.review !== 'boolean') return undefined
  return { cls, review: o.review }
}

export const rungOf = (table: DispatchTable, c: Classification): Rung => (c.review ? table.review : table.rows)[c.cls]

export const rungName = (r: { model: string; effort: string }): string => `${r.model}/${r.effort}`

// What DESIGN or the table say once the explicit facts are set aside (route.ts and effort.ts put those first): the
// model and the effort to take, who said so, and for the table the class and the rung.
export type Steer =
  | { by: 'design'; model?: Family; effort?: Effort }
  | { by: 'table'; model: Rung['model']; effort: Effort; cls: TaskClass; review: boolean; rung: string }
  | { by: 'unclassified'; why: string }
  | { by: 'none' }

// DESIGN and the table steer only a model's own Agent call that starts an agent: never a fork, a workflow agent, a
// teammate, a spawn no Agent call was seen for, or a resume. A class given for a spawn that is not classifiable is
// not read.
export const steerOf = (f: DispatchFacts, table: DispatchTable, classified: Classified): Steer => {
  if (f.fixed || !f.seen || f.resumed) return { by: 'none' }
  if (f.design.model !== undefined || f.design.effort !== undefined) {
    return { by: 'design', ...(f.design.model === undefined ? {} : { model: f.design.model }), ...(f.design.effort === undefined ? {} : { effort: f.design.effort }) }
  }
  if (classified === undefined || !classifiable(f)) return { by: 'none' }
  if ('failed' in classified) return { by: 'unclassified', why: classified.failed }
  const r = rungOf(table, classified)
  return { by: 'table', model: r.model, effort: r.effort, cls: classified.cls, review: classified.review, rung: rungName(r) }
}

files.hooks/shell.ts:
// The commands a Bash command line runs, read in one pass the way the shell reads them: quotes, `$(...)`,
// backticks, backslash continuations and heredocs span lines, so a line is no unit of a command.
// source: the POSIX Shell Command Language (XCU 2.2 Quoting, 2.3 Token Recognition, 2.6.3 Command
// Substitution, 2.7.4 Here-Document, 2.9 Shell Commands) and bash's manual for `<<<`, `&>`, `|&` and `$'...'`.
//
// Invariant of the scan, held at every step: `i` is the first character not yet read; every character before
// it belongs to exactly one of a word of the current command, an operator, a comment, a continuation, or the
// body of a heredoc whose operator was read on an earlier line. Hence a quoted, substituted or heredoc
// character never ends a command, and a separator ends one only where the shell reads it as one.

// One simple command: its words with each quoted span and substitution as `''` (a head, an option and a
// separator are read on it only where the shell reads them), the source text it came from (inline code
// is read there), and the files it redirects output into, spelled as the shell would open them.
export type ShellCommand = { bare: string; raw: string; targets: string[] }

type Word = { literal: string; bare: string; quoted: boolean }
type Doc = { end: string; dash: boolean; expands: boolean }

const BLANK = /[ \t]/ // source: XCU 2.3, a <blank> delimits a token
// The characters that end an unquoted word (XCU 2.2: the metacharacters, and the newline).
const META = /[ \t\n;&|()<>]/
// At the start of a token: an operator that redirects (`2>&1`, `&>`, `>|`, `<<-`, `<<<`), or one that ends a command.
const REDIRECT_OP = /^(?:[0-9]+)?(?:>>|>\||>&|>|<<<|<<-|<<|<&|<>|<)|^&>>?/
const SEPARATOR_OP = /^(?:&&|\|\||\|&|;;|;|\||&)/
// A duplicated descriptor (`>&2`, `>&-`) opens no file.
const DESCRIPTOR = /^([0-9]+|-)$/

export const shellCommands = (src: string): ShellCommand[] => {
  const out: ShellCommand[] = []
  let i = 0
  // Heredocs whose operator was read on the current line: their bodies start at its newline, in order.
  let pending: Doc[] = []

  // A heredoc body is whole lines up to its terminator (leading tabs stripped for `<<-`). An unquoted
  // delimiter's body is expanded by the shell, so its substitutions run; a quoted one's is data.
  const bodies = (): void => {
    const docs = pending
    pending = []
    for (const d of docs) {
      while (i < src.length) {
        const nl = src.indexOf('\n', i)
        const stop = nl === -1 ? src.length : nl
        const line = src.slice(i, stop)
        if ((d.dash ? line.replace(/^\t+/, '') : line) === d.end) {
          i = nl === -1 ? src.length : nl + 1
          break
        }
        if (d.expands) expanding(stop)
        i = nl === -1 ? src.length : nl + 1
      }
    }
  }

  // Text where only `\`, `$(` and backticks are special (inside double quotes, or an expanding heredoc body),
  // up to `stop` or the closing `"` when `quote` is set.
  const expanding = (stop: number, quote = false): string => {
    let literal = ''
    while (i < stop) {
      const c = src[i] ?? ''
      if (quote && c === '"') {
        i += 1
        return literal
      }
      if (c === '\\') {
        const n = src[i + 1] ?? ''
        i += 2
        if (n !== '\n') literal += '$`"\\'.includes(n) ? n : `\\${n}`
        continue
      }
      if (c === '$' && src[i + 1] === '(') {
        substitution()
        literal += '$()'
        continue
      }
      if (c === '`') {
        i += 1
        list('`')
        literal += '$()'
        continue
      }
      literal += c
      i += 1
    }
    return literal
  }

  // `$(...)` runs its commands; `$((...))` is arithmetic, a value.
  const substitution = (): void => {
    if (src[i + 2] === '(') {
      let depth = 0
      while (i < src.length) {
        const c = src[i]
        i += 1
        if (c === '(') depth += 1
        else if (c === ')' && --depth === 0) return
      }
      return
    }
    i += 2
    list(')')
  }

  // One word: unquoted text, quoted spans and substitutions, up to a blank or a metacharacter.
  const word = (close: string): Word => {
    let literal = ''
    let bare = ''
    let quoted = false
    while (i < src.length) {
      const c = src[i] ?? ''
      if (META.test(c) || c === close) break
      if (c === "'") {
        const end = src.indexOf("'", i + 1)
        const stop = end === -1 ? src.length : end
        literal += src.slice(i + 1, stop)
        i = stop + 1
        bare += "''"
        quoted = true
      } else if (c === '"') {
        i += 1
        literal += expanding(src.length, true)
        bare += "''"
        quoted = true
      } else if (c === '$' && src[i + 1] === "'") {
        i += 2
        while (i < src.length && src[i] !== "'") i += src[i] === '\\' ? 2 : 1
        i += 1
        bare += "''"
        quoted = true
      } else if (c === '$' && src[i + 1] === '(') {
        substitution()
        literal += '$()'
        bare += "''"
      } else if (c === '`') {
        i += 1
        list('`')
        literal += '$()'
        bare += "''"
      } else if (c === '$' && src[i + 1] === '{') {
        const end = src.indexOf('}', i)
        const stop = end === -1 ? src.length : end + 1
        literal += src.slice(i, stop)
        bare += src.slice(i, stop)
        i = stop
      } else if (c === '\\') {
        const n = src[i + 1] ?? ''
        i += 2
        if (n === '\n') continue
        literal += n
        bare += /[\w./:=+,@%-]/.test(n) ? n : '_'
        quoted = true
      } else {
        literal += c
        bare += c
        i += 1
      }
    }
    return { literal, bare, quoted }
  }

  const blanks = (): void => {
    while (i < src.length) {
      if (BLANK.test(src[i] ?? '')) i += 1
      else if (src[i] === '\\' && src[i + 1] === '\n') i += 2
      else return
    }
  }

  // The commands up to `close` (`)` of `$(`, a backtick, or '' for the end of the text); `i` is left past it.
  const list = (close: string): void => {
    let words: string[] = []
    let targets: string[] = []
    let start = i
    let depth = 0 // subshells opened inside this list: their `)` ends a command, not the list
    const finish = (): void => {
      if (words.length > 0 || targets.length > 0) out.push({ bare: words.join(' '), raw: src.slice(start, i).trim(), targets })
      words = []
      targets = []
    }
    while (true) {
      blanks()
      if (words.length === 0 && targets.length === 0) start = i
      if (i >= src.length) break
      const c = src[i] ?? ''
      const rest = src.slice(i, i + 4)
      if (c === close && !(close === ')' && depth > 0)) {
        finish()
        i += 1
        return
      }
      if (c === '\n') {
        finish()
        i += 1
        bodies()
        continue
      }
      if (c === '#') {
        while (i < src.length && src[i] !== '\n') i += 1
        continue
      }
      if (c === '(' || c === ')') {
        finish()
        depth = Math.max(0, depth + (c === '(' ? 1 : -1))
        i += 1
        continue
      }
      const redirect = REDIRECT_OP.exec(rest)?.[0]
      if (redirect !== undefined) {
        i += redirect.length
        blanks()
        const op = redirect.replace(/^[0-9]+/, '')
        const target = word(close)
        if (op === '<<' || op === '<<-') pending.push({ end: target.literal, dash: op === '<<-', expands: !target.quoted })
        else if (op.startsWith('<') && op !== '<>') continue
        else if (op.endsWith('&') && DESCRIPTOR.test(target.literal)) continue
        else targets.push(target.literal)
        continue
      }
      const separator = SEPARATOR_OP.exec(rest)?.[0]
      if (separator !== undefined) {
        finish()
        i += separator.length
        continue
      }
      const before = i
      const w = word(close)
      if (i === before) i += 1 // a character no rule above reads: skipped, so the scan always moves on
      else words.push(w.bare)
    }
    finish()
  }

  list('')
  return out
}

